import{_ as a,o as e,c as i,ag as n}from"./chunks/framework.BGkQCay2.js";const k=JSON.parse('{"title":"Ownership","description":"","frontmatter":{},"headers":[],"relativePath":"guide/memory/ownership.md","filePath":"guide/memory/ownership.md"}'),t={name:"guide/memory/ownership.md"};function l(p,s,r,o,h,d){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h1><p>Vex uses ownership to make the lifetime and movement of values explicit. A value has one owner. Passing an owning value to a function or assigning it to another binding can move that ownership; borrowing lets code use the value without taking it over.</p><p>The ownership and borrow checker are implemented in the current compiler. The exact behavior of container, runtime, and FFI types still depends on their API contracts.</p><h2 id="bindings-and-mutation" tabindex="-1">Bindings and mutation <a class="header-anchor" href="#bindings-and-mutation" aria-label="Permalink to &quot;Bindings and mutation&quot;">​</a></h2><p>Bindings are immutable by default:</p><div class="language-vex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use let! when the binding must be reassigned:</p><div class="language-vex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    let!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> total </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    total </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> total;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A mutable binding does not make every reference to the value mutable. The reference type must also permit mutation.</p><h2 id="moves" tabindex="-1">Moves <a class="header-anchor" href="#moves" aria-label="Permalink to &quot;Moves&quot;">​</a></h2><p>Owning values such as Vec, Box, strings, maps, sets, and most user-defined structs may be moved:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let data = Vec.new&lt;i32&gt;()</span></span>
<span class="line"><span>let moved = data</span></span>
<span class="line"><span>use(moved)</span></span>
<span class="line"><span>use(data) // error: data was moved</span></span></code></pre></div><p>A move is useful when a function or task should become the new owner. If the caller still needs to use the value, pass an immutable or mutable reference instead.</p><h2 id="copy-values" tabindex="-1">Copy values <a class="header-anchor" href="#copy-values" aria-label="Permalink to &quot;Copy values&quot;">​</a></h2><p>Small scalar values such as integers, floating-point values, booleans, and characters are copied in ordinary assignments:</p><div class="language-vex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> first</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> second </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> first;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    $</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">println(first);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> second;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>For an owning or user-defined type, assume that assignment moves unless the type&#39;s contract says otherwise.</p><h2 id="borrowing" tabindex="-1">Borrowing <a class="header-anchor" href="#borrowing" aria-label="Permalink to &quot;Borrowing&quot;">​</a></h2><p>An immutable borrow uses &amp;T:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn inspect(value: &amp;Point): i32 {</span></span>
<span class="line"><span>    value.x + value.y</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>A mutable borrow uses &amp;T!:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn update(value: &amp;Point!) {</span></span>
<span class="line"><span>    value.x = 10</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>There may be several immutable borrows, or one exclusive mutable borrow, but the two kinds cannot conflict while they are live. The checker uses non-lexical lifetime reasoning, so an immutable borrow can end at its last use rather than at the end of the surrounding block.</p><h2 id="partial-moves" tabindex="-1">Partial moves <a class="header-anchor" href="#partial-moves" aria-label="Permalink to &quot;Partial moves&quot;">​</a></h2><p>Ownership is tracked at the field level for supported structs. Moving one non-Copy field does not automatically move every independent field:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct Pair {</span></span>
<span class="line"><span>    public:</span></span>
<span class="line"><span>    name: string,</span></span>
<span class="line"><span>    age: i32,</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let pair = Pair { name: &quot;Alice&quot;, age: 30 }</span></span>
<span class="line"><span>let name = pair.name</span></span>
<span class="line"><span>use(pair.age)</span></span></code></pre></div><p>The moved field cannot be read again. Copy fields can remain available when the surrounding type and access path permit it.</p><h2 id="references-returned-from-functions" tabindex="-1">References returned from functions <a class="header-anchor" href="#references-returned-from-functions" aria-label="Permalink to &quot;References returned from functions&quot;">​</a></h2><p>A returned reference must be derived from data that outlives the returned reference:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn longest(left: &amp;string, right: &amp;string): &amp;string {</span></span>
<span class="line"><span>    if left.len() &gt; right.len() {</span></span>
<span class="line"><span>        return left</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return right</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Returning a reference to a local owned value is rejected because the local is destroyed when the function returns.</p><h2 id="heap-owned-values" tabindex="-1">Heap-owned values <a class="header-anchor" href="#heap-owned-values" aria-label="Permalink to &quot;Heap-owned values&quot;">​</a></h2><p>Box is an owning heap value. It is useful when a value needs indirection or a recursive data structure needs a stable allocation:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let boxed = Box.new(42)</span></span>
<span class="line"><span>use(boxed)</span></span></code></pre></div><p>Box does not bypass ownership. Moving, borrowing, and dropping a boxed value still follow the same rules.</p><h2 id="low-level-views" tabindex="-1">Low-level views <a class="header-anchor" href="#low-level-views" aria-label="Permalink to &quot;Low-level views&quot;">​</a></h2><p>Use the narrowest memory abstraction that expresses the operation:</p><ul><li>&amp;T and &amp;T! for ordinary borrows;</li><li><code>Span&lt;T&gt;</code> for a non-owning contiguous view;</li><li><code>Ptr&lt;T&gt;</code> for typed pointer operations;</li><li>RawBuf for explicit raw storage.</li></ul><p>Keep raw memory and FFI code behind a small, tested boundary. See <a href="/docs/guide/ffi">FFI</a>, <a href="/docs/guide/advanced/pointers">Pointers</a>, and <a href="/docs/guide/memory/safety">Memory Safety</a>.</p><h2 id="practical-rules" tabindex="-1">Practical rules <a class="header-anchor" href="#practical-rules" aria-label="Permalink to &quot;Practical rules&quot;">​</a></h2><ol><li>Borrow when the callee should not become the owner.</li><li>Move when ownership transfer is intentional.</li><li>Make mutation visible with let! and mutable references.</li><li>Use explicit types at FFI and ABI boundaries.</li><li>Check detached-task captures carefully; a go block cannot safely outlive a borrowed local.</li></ol><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/guide/memory/borrowing">Borrowing</a></li><li><a href="/docs/guide/memory/lifetimes">Lifetimes</a></li><li><a href="/docs/guide/memory/safety">Memory Safety</a></li><li><a href="/docs/guide/memory/vumm">VUMM</a></li></ul>`,43)])])}const u=a(t,[["render",l]]);export{k as __pageData,u as default};
